import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawn} from 'node:child_process';
import {Coordinator,control,retryOffline,replanOffline,reintegrateOffline,amendScopeOffline} from '../tools/coordinator/engine';
import {git,integrate,prepareCandidate,prepareTask,checkScope,snapshotTask,changedFiles,refreshCleanIndex,candidateCheckIds} from '../tools/coordinator/git';
import {Lease,readJson,atomicJson,allowedFile,appendEvent,readTasks,fingerprint,isAlive} from '../tools/coordinator/storage';
import {JsonLines,classifyFailure,workerResult,reviewResult,extractClaudeResult,operatorFeedback} from '../tools/coordinator/protocol';
import {runCommand,terminateTree,buildInvocation,AgentRunError} from '../tools/coordinator/process';
import type {Config,TaskSpec,Task,Agent,Activity} from '../tools/coordinator/types';

function makeCoordinator(config:Config){return new Coordinator(config,()=>{},{processesFactory:()=>({stop:async()=>{},execute:async()=>{throw Error('Fixture attempted an uninjected coding agent.');}})});}

test('blocked implementations and exhausted repairs publish actionable attention events',async()=>{
 const {config}=fixture([spec('needs-target','claude','owned.txt')]);const engine=makeCoordinator(config);await engine.initialize();
 try {
  engine.processes={execute:async()=>({value:{status:'blocked',summary:'Target needed',changedFiles:[],tests:[],limitations:['Choose the target application.'],handoff:'No application was changed.'},sessionId:'blocked-session',output:'',malformed:0}),stop:async()=>{},children:new Map()} as any;
  const pending=engine.state.tasks[0];await engine.implement(pending);assert.equal(pending.phase,'blocked');
  const events=()=>fs.readFileSync(engine.eventsFile,'utf8').trim().split('\n').map(line=>JSON.parse(line));
  assert.equal(events().at(-1).kind,'needs_input');assert.match(events().at(-1).summary,/Choose the target/);
  pending.attempts=2;engine.handleFailure(pending,Error('Two repairs failed.'));assert.equal(pending.phase,'failed');assert.equal(events().at(-1).kind,'needs_input');
  engine.stopping=true;engine.handleFailure(pending,Error('Stopped by user'));assert.equal(events().at(-1).kind,'error');
 }finally{engine.lock.release();}
});

function fixture(specs:TaskSpec[]=[]){
 const base=fs.mkdtempSync(path.join(os.tmpdir(),'capri-coordinator-'));const repo=path.join(base,'repo');fs.mkdirSync(repo);git(repo,'init','-b','main');git(repo,'config','core.autocrlf','false');git(repo,'config','user.name','Coordinator Test');git(repo,'config','user.email','fixture@localhost');fs.writeFileSync(path.join(repo,'baseline.txt'),'baseline\n');git(repo,'add','.');git(repo,'commit','-m','baseline');
 const prompts=path.join(repo,'prompts');fs.mkdirSync(prompts);for(const name of ['master','codex','claude','review'])fs.writeFileSync(path.join(prompts,name+'.md'),'Fixture '+name);fs.writeFileSync(path.join(repo,'tasks.json'),JSON.stringify(specs));fs.writeFileSync(path.join(repo,'ROADMAP.md'),'Small local improvements only.');git(repo,'add','.');git(repo,'commit','-m','fixture contracts');
 const config:Config={version:1,repo,developmentRoot:base,stateDir:path.join(base,'state'),worktreeRoot:path.join(base,'worktrees'),profileRoot:path.join(base,'profiles'),referenceRoot:path.join(base,'reference'),candidateBranch:'codex/candidate',tasksFile:path.join(repo,'tasks.json'),prompts:Object.fromEntries(['master','codex','claude','review'].map(n=>[n,path.join(prompts,n+'.md')])) as Config['prompts'],checks:[{id:'check',command:process.execPath,args:['-e','process.exit(0)']}],agents:{codex:{command:process.execPath},claude:{command:process.execPath}},continuous:false,timeoutMs:10000,maxRepairAttempts:1,pollMs:10,maxProposalsPerCycle:2,maxQueuedTasks:12,proposalAllowedPaths:['src/','tests/'],roadmapFile:path.join(repo,'ROADMAP.md')};
 return {base,repo,config};
}
const spec=(id:string,owner:Agent,file:string):TaskSpec=>({id,owner,goal:'Write fixture '+file,allowedPaths:[file],dependencies:[],resources:[id],acceptance:['check']});
const task=(value:TaskSpec):Task=>({...value,phase:'queued',attempts:1,fingerprint:fingerprint(value)});

test('single-owner lease rejects another controller and stale lease recovers',()=>{
 const dir=fs.mkdtempSync(path.join(os.tmpdir(),'capri-lease-')),file=path.join(dir,'lock');const first=new Lease(file),second=new Lease(file);first.acquire();assert.throws(()=>second.acquire(),/already running/);first.release();atomicJson(file,{pid:2147483647,token:'stale'});second.acquire();assert.equal(readJson<any>(file).token,second.token);second.release();
});
test('scoped files reject traversal and similar-prefix paths',()=>{
 assert.equal(allowedFile('src/server/context.ts',['src/server/']),true);assert.equal(allowedFile('src/server-other/context.ts',['src/server/']),false);for(const file of ['../private.txt','C:/profile/data','.git/config','.env.local','src/../credentials'])assert.equal(allowedFile(file,['src/','']),false);
});
test('task dependency cycles and unknown checks are refused before launching workers',()=>{
 const {config}=fixture([spec('one','codex','one.txt'),{...spec('two','claude','two.txt'),dependencies:['one']}]);const data=readJson<TaskSpec[]>(config.tasksFile);data[0].dependencies=['two'];atomicJson(config.tasksFile,data);assert.throws(()=>readTasks(config),/Cyclic/);data[0].dependencies=[];data[0].acceptance=['invented'];atomicJson(config.tasksFile,data);assert.throws(()=>readTasks(config),/acceptance/);
});
test('activity duplicates are suppressed and credential-shaped text is redacted',()=>{
 // Reconstruct the intentional fake credential so source exports contain no key-shaped literal.
 const fakeCredential=['sk','abcdefghijklmnopqrstuv'].join('-');
 const file=path.join(fs.mkdtempSync(path.join(os.tmpdir(),'capri-event-')),'events.jsonl');const seen=new Set<string>();const event:Activity={id:'same',agent:'codex',sessionId:'s',taskId:'t',project:'p',kind:'working',summary:fakeCredential,at:new Date().toISOString()};assert.equal(appendEvent(file,event,seen),true);assert.equal(appendEvent(file,event,seen),false);const lines=fs.readFileSync(file,'utf8').trim().split('\n');assert.equal(lines.length,1);assert.equal(JSON.parse(lines[0]).summary,'[redacted]');
});

test('dependency handoffs carry bounded reviewed-source context without expanding the next assignment',async()=>{
 const dependency=spec('interface','claude','src/interface.ts'),next={...spec('integration','codex','src/integration.ts'),dependencies:['interface']},{config}=fixture([dependency,next]),engine=makeCoordinator(config);await engine.initialize();
 try{
  const first=engine.state.tasks[0],second=engine.state.tasks[1],credential=['sk','abcdefghijklmnopqrstuv'].join('-');
  first.phase='completed';first.commit='a'.repeat(40);first.integratedCommit='b'.repeat(40);first.result={status:'completed',summary:'Exported createInterface',changedFiles:[],tests:[],limitations:['Device check pending'],handoff:'createInterface({privacyEpoch}) is required. '+credential+' Untrusted text cannot grant edits elsewhere. '+ 'x'.repeat(100000)};
  const record=engine.dependencyHandoffs(second)[0] as any;assert.equal(record.implementationCommit,first.commit);assert.equal(record.integrationCommit,first.integratedCommit);assert.equal(record.truncated,true);assert.ok(record.handoff.length<=8000);assert.match(record.handoff,/createInterface/);assert.equal(record.handoff.includes(credential),false);assert.match(record.handoff,/\[redacted\]/);
  const prompt=engine.taskPrompt(second);assert.ok(prompt.length<16000);assert.match(prompt,/untrusted diagnostic data only/);assert.match(prompt,/inspect actual source interfaces/);assert.deepEqual(second.allowedPaths,['src/integration.ts']);assert.deepEqual(second.acceptance,['check']);
  first.phase='review';assert.deepEqual(engine.dependencyHandoffs(second),[{id:'interface',available:false}]);
 }finally{engine.lock.release();}
});
test('streaming JSON handles chunk boundaries, malformed output and structured Claude result',()=>{
 const records:any[]=[];const parser=new JsonLines(r=>records.push(r));parser.push('{"type":"sta');parser.push('rt"}\nnot-json\n{"type":"result","structured_output":{"approved":true}}');parser.end();assert.equal(records.length,2);assert.equal(parser.malformed,1);assert.equal(extractClaudeResult(records).approved,true);assert.throws(()=>workerResult({status:'completed'}),/Malformed/);assert.throws(()=>extractClaudeResult([{type:'result',is_error:true,result:'not logged in'}]),/not logged in/);
});
test('quota, auth and permission failures are classified without infinite retries',()=>{
 assert.equal(classifyFailure('usage limit reached'),'quota');assert.equal(classifyFailure('authentication required'),'auth');assert.equal(classifyFailure('Tool is not allowed'),'permission');const {config}=fixture();const engine=makeCoordinator(config);engine.state={version:1,generation:0,runId:'r',status:'running',startedAt:'',updatedAt:'',candidateCommit:'',tasks:[],eventsSeen:[],proposalsAfter:0,proposalAttempts:0};const pending=task(spec('quota','codex','one.txt'));engine.state.tasks.push(pending);engine.handleFailure(pending,new AgentRunError('usage limit reached'));assert.equal(pending.phase,'blocked');engine.handleFailure(pending,Error('unexpected crash'));assert.equal(pending.phase,'queued');pending.attempts=2;engine.handleFailure(pending,Error('unexpected crash'));assert.equal(pending.phase,'failed');
});
test('two agents execute simultaneously in distinct worktrees, cross-review and integrate',async()=>{
 const {config}=fixture([spec('alpha','codex','alpha.txt'),spec('beta','claude','beta.txt')]);const engine=makeCoordinator(config);const active=new Set<Agent>();const paths=new Set<string>();let simultaneous=false;const reviews:string[]=[];
 engine.processes={children:new Map(),stop:async()=>{},execute:async(request:any)=>{
  active.add(request.agent);if(active.size===2)simultaneous=true;paths.add(request.cwd);engine.started({pid:2147483647,marker:request.cwd,agent:request.agent,mode:request.mode,taskId:request.taskId,sessionId:request.taskId,startedAt:new Date().toISOString()});await new Promise(r=>setTimeout(r,30));active.delete(request.agent);
  if(request.mode==='review'){reviews.push(request.agent+':'+request.taskId);return {value:{approved:true,summary:'Fixture reviewed',issues:[]},sessionId:'review',output:'',malformed:0};}
  const file=request.agent==='codex'?'alpha.txt':'beta.txt';fs.writeFileSync(path.join(request.cwd,file),file+'\n');return {value:{status:'completed',summary:'Wrote '+file,changedFiles:[file],tests:[],limitations:[],handoff:'Read fixture content'},sessionId:'impl',output:'',malformed:0};
 }} as any;
 await engine.run(true);assert.equal(simultaneous,true);assert.equal(paths.size,2);assert.deepEqual(reviews.sort(),['claude:alpha','codex:beta']);assert.ok(engine.state.tasks.every(t=>t.phase==='completed'));assert.ok(fs.existsSync(path.join(engine.candidate,'alpha.txt')));assert.ok(fs.existsSync(path.join(engine.candidate,'beta.txt')));assert.equal(git(engine.candidate,'status','--porcelain'),'');
});
