 const generated='android/app/src/main/assets/voice.js',{repo,config}=fixture();fs.mkdirSync(path.dirname(path.join(repo,generated)),{recursive:true});fs.writeFileSync(path.join(repo,'.gitattributes'),'*.js text eol=lf\n');fs.writeFileSync(path.join(repo,generated),'const voice = 1;\n');git(repo,'add','.gitattributes',generated);git(repo,'commit','-m','generated LF bundle');const candidate=prepareCandidate(config),pending=task(spec('generated-integration','claude',generated));prepareTask(config,pending,candidate,'generated-integration');fs.writeFileSync(path.join(pending.worktree!,generated),'const voice = 2;\n');pending.result={status:'completed',summary:'Updated generated voice',changedFiles:[generated],tests:[],limitations:[],handoff:''};snapshotTask(pending);fs.writeFileSync(path.join(candidate,generated),'const voice = 1;\r\n');assert.ok(git(candidate,'status','--porcelain').includes(generated));assert.deepEqual(changedFiles(candidate),[]);const expected=git(candidate,'rev-parse','HEAD^{tree}');refreshCleanIndex(candidate);assert.equal(git(candidate,'write-tree'),expected);await integrate(config,pending,candidate);assert.equal(fs.readFileSync(path.join(candidate,generated),'utf8'),'const voice = 2;\n');
