test('operator reintegration preserves approved commit and attempt history and runs all candidate checks',async()=>{
 const {config}=fixture([spec('accepted','claude','src/accepted.ts')]),seed=makeCoordinator(config);await seed.initialize();const pending=seed.state.tasks[0];pending.attempts=2;prepareTask(config,pending,seed.candidate,'accepted');fs.mkdirSync(path.join(pending.worktree!,'src'));fs.writeFileSync(path.join(pending.worktree!,'src/accepted.ts'),'export const accepted = true;\n');pending.result={status:'completed',summary:'Accepted implementation',changedFiles:['src/accepted.ts'],tests:[],limitations:[],handoff:''};snapshotTask(pending);pending.review={approved:true,summary:'Opposite agent approved',issues:[]};pending.reviewHistory=[{at:new Date().toISOString(),attempt:2,reviewer:'codex',review:pending.review,commit:pending.commit}];pending.phase='failed';pending.integrationFailure={at:new Date().toISOString(),commit:pending.commit!,candidateCommit:seed.state.candidateCommit,error:'Recorded Git index failure'};seed.save();const commit=pending.commit,history=JSON.parse(JSON.stringify(pending.reviewHistory));seed.lock.release();const queued=reintegrateOffline(config,pending.id,'Refresh proven-clean index and apply same approved commit');assert.equal(queued.phase,'integration');assert.equal(queued.commit,commit);assert.equal(queued.attempts,2);assert.deepEqual(queued.reviewHistory,history);assert.equal(queued.reintegrationHistory?.length,1);const marker=path.join(config.stateDir,'checks.log');config.checks=['check','second'].map(id=>({id,command:process.execPath,args:['-e',"const fs=require('node:fs');if(!fs.existsSync('src/accepted.ts'))process.exit(1);fs.appendFileSync(process.argv[1],process.argv[2]+'\\n')",marker,id]}));const engine=makeCoordinator(config);engine.processes={children:new Map(),stop:async()=>{},execute:async()=>{throw Error('Reintegration must not spawn implementation or review workers');}} as any;await engine.run(true,true);assert.equal(engine.state.tasks[0].phase,'completed');assert.equal(engine.state.tasks[0].commit,commit);assert.equal(engine.state.tasks[0].attempts,2);assert.deepEqual(engine.state.tasks[0].reviewHistory,history);assert.deepEqual(fs.readFileSync(marker,'utf8').trim().split('\n'),['check','second']);assert.ok(engine.state.tasks[0].validation?.some(check=>check.id==='candidate:second'&&check.passed));
});
test('reintegration rejects unreviewed, owner-reviewed, tampered and unreconciled cases',async()=>{
 const {config}=fixture([spec('guarded','claude','owned.txt')]),engine=makeCoordinator(config);await engine.initialize();try{const pending=engine.state.tasks[0];pending.attempts=2;prepareTask(config,pending,engine.candidate,'guarded');fs.writeFileSync(path.join(pending.worktree!,'owned.txt'),'reviewed\n');pending.result={status:'completed',summary:'Reviewed change',changedFiles:['owned.txt'],tests:[],limitations:[],handoff:''};snapshotTask(pending);pending.phase='failed';pending.error='Candidate restored to '+engine.state.candidateCommit+'. Diagnostics preserved: fixture';pending.review={approved:true,summary:'Approved legacy review',issues:[]};pending.reviewHistory=[{at:'legacy',attempt:2,reviewer:'codex',review:pending.review}];pending.review.approved=false;assert.throws(()=>engine.reintegrateTask(pending.id,'Do not bypass review'),/approved opposite/);pending.review.approved=true;pending.reviewHistory[0].reviewer='claude';assert.throws(()=>engine.reintegrateTask(pending.id,'Do not accept owner review'),/approved opposite/);pending.reviewHistory[0].reviewer='codex';fs.writeFileSync(path.join(pending.worktree!,'owned.txt'),'tampered\n');assert.throws(()=>engine.reintegrateTask(pending.id,'Reject tampering'),/checkout was modified/);fs.writeFileSync(path.join(pending.worktree!,'owned.txt'),'reviewed\n');const recorded=engine.state.candidateCommit;engine.state.candidateCommit='0'.repeat(40);assert.throws(()=>engine.reintegrateTask(pending.id,'Reject unexpected candidate'),/checkpoint/);engine.state.candidateCommit=recorded;pending.error='Independent task validation failed';assert.throws(()=>engine.reintegrateTask(pending.id,'Not an integration failure'),/recorded integration failure/);pending.error='Candidate restored to '+recorded+'. Diagnostics preserved: fixture';const commit=pending.commit;control(config,'reintegrate',{taskId:pending.id,feedback:'Operator accepted legacy review binding; rerun all integration checks'});await engine.consumeControl();assert.equal(pending.phase,'integration');assert.equal(pending.commit,commit);assert.equal(pending.attempts,2);assert.equal(pending.reintegrationHistory?.length,1);}finally{engine.lock.release();}
});
test('merge-conflict repairs use a fresh candidate base and preserve the failed approved worktree',async()=>{
 const {repo,config}=fixture([spec('conflict-repair','codex','shared.txt')]);fs.writeFileSync(path.join(repo,'shared.txt'),"const left = 'base';\nconst right = 'base';\n");git(repo,'add','shared.txt');git(repo,'commit','-m','shared interface');const engine=makeCoordinator(config);await engine.initialize();try{const pending=engine.state.tasks[0];pending.attempts=1;prepareTask(config,pending,engine.candidate,'old-base');fs.writeFileSync(path.join(pending.worktree!,'shared.txt'),"const left = 'worker';\nconst right = 'base';\n");pending.result={status:'completed',summary:'Old approved implementation',changedFiles:['shared.txt'],tests:[],limitations:[],handoff:''};snapshotTask(pending);const originalWorktree=pending.worktree!,originalCommit=pending.commit!;pending.review={approved:true,summary:'Original approved',issues:[]};pending.reviewHistory=[{at:'before-conflict',attempt:1,reviewer:'claude',review:pending.review,commit:originalCommit}];pending.phase='integration';fs.writeFileSync(path.join(engine.candidate,'shared.txt'),"const left = 'candidate';\nconst right = 'new-interface';\n");fs.writeFileSync(path.join(engine.candidate,'interface.txt'),'latest interface\n');git(engine.candidate,'add','shared.txt','interface.txt');git(engine.candidate,'commit','-m','another accepted candidate interface');engine.state.candidateCommit=git(engine.candidate,'rev-parse','HEAD');const repairBase=engine.state.candidateCommit;await engine.combine(pending);assert.equal(pending.phase,'queued');assert.equal(pending.commit,originalCommit);assert.equal(pending.integrationFailure?.commit,originalCommit);let implementations=0,reviews=0;engine.processes={children:new Map(),stop:async()=>{},execute:async(request:any)=>{if(request.mode==='review'){reviews++;return {value:{approved:true,summary:'Fresh repair approved',issues:[]},sessionId:'repair-review',output:'',malformed:0};}implementations++;assert.notEqual(request.cwd,originalWorktree);assert.equal(git(request.cwd,'rev-parse','HEAD'),repairBase);assert.equal(fs.readFileSync(path.join(request.cwd,'interface.txt'),'utf8'),'latest interface\n');assert.ok(fs.readFileSync(path.join(request.cwd,'shared.txt'),'utf8').includes('<<<<<<<'));assert.equal(fs.existsSync(path.join(git(request.cwd,'rev-parse','--git-dir'),'CHERRY_PICK_HEAD')),false);fs.writeFileSync(path.join(request.cwd,'shared.txt'),"const left = 'worker-on-candidate';\nconst right = 'new-interface';\n");return {value:{status:'completed',summary:'Resolved against current interface',changedFiles:['shared.txt'],tests:[],limitations:[],handoff:'New candidate preserved'},sessionId:'repair-implementation',output:'',malformed:0};}} as any;await engine.implement(pending);assert.equal(pending.phase,'review');assert.equal(pending.baseCommit,repairBase);assert.equal(git(originalWorktree,'rev-parse','HEAD'),originalCommit);assert.ok(fs.readFileSync(path.join(originalWorktree,'shared.txt'),'utf8').includes("left = 'worker'"));assert.equal(pending.integrationRepairHistory?.[0].previousWorktree,originalWorktree);assert.equal(pending.integrationRepairHistory?.[0].commit,originalCommit);await engine.review(pending,'claude');assert.equal(pending.phase,'integration');await engine.combine(pending);assert.equal(pending.phase,'completed');assert.equal(pending.attempts,2);assert.equal(implementations,1);assert.equal(reviews,1);assert.ok(fs.readFileSync(path.join(engine.candidate,'shared.txt'),'utf8').includes("right = 'new-interface'"));assert.equal(fs.readFileSync(path.join(engine.candidate,'interface.txt'),'utf8'),'latest interface\n');}finally{engine.lock.release();}
});
