test('Stop command is idempotent after natural exit and handles the disappearing-lock read race',async()=>{
 const {base,config}=fixture(),engine=makeCoordinator(config);await engine.run(true);const stateBefore=fs.readFileSync(engine.stateFile,'utf8'),configFile=path.join(base,'stop-config.json'),cli=path.resolve('tools/coordinator/cli.ts');atomicJson(configFile,config);for(let attempt=0;attempt<2;attempt++){const result=await runCommand(process.execPath,['--import','tsx',cli,'stop','--config',configFile],process.cwd(),10000);assert.equal(result.code,0,result.output);assert.match(result.output,/already stopped/);}const bootstrap=path.join(base,'stop-race.mjs');fs.writeFileSync(bootstrap,"import fs from 'node:fs';import path from 'node:path';import {pathToFileURL} from 'node:url';const [cli,config,lock]=process.argv.slice(2);fs.writeFileSync(lock,JSON.stringify({pid:process.pid,token:'exiting-controller'}));const read=fs.readFileSync;let reads=0;fs.readFileSync=function(file,...args){const result=read.call(fs,file,...args);if(path.resolve(String(file))===path.resolve(lock)&&++reads===1)fs.unlinkSync(lock);return result;};process.argv=[process.execPath,cli,'stop','--config',config];await import(pathToFileURL(cli).href);");const raced=await runCommand(process.execPath,['--import','tsx',bootstrap,cli,configFile,engine.lock.file],process.cwd(),10000);assert.equal(raced.code,0,raced.output);assert.match(raced.output,/already stopped/);assert.equal(fs.readFileSync(engine.stateFile,'utf8'),stateBefore);assert.equal(fs.existsSync(engine.lock.file),false);assert.equal(fs.existsSync(engine.controlFile),false);
});
